internal final class AVABPMasterDataReportController extends  SrsReportRunController
{
    Args                        clsArgs;
    KCS_KBVBuildingProjectTable clsKCS_KBVBuildingProjectTable;
    boolean                     clsPreviewMode;

}

Method.Source:
/// <summary>
///    AVA <c>construct</c> method.
/// </summary>
/// <returns>
///    <c>AVABPMasterDataReportController</c> as return value
/// </returns>
public static AVABPMasterDataReportController construct()
{
    return new AVABPMasterDataReportController();
}

/// <summary>
///    AVA <c>parmArgs</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>RefRecId</c> as type
/// </param>
/// <returns>
///    <c>Args</c> as return value
/// </returns>
public Args parmArgs(Args _parmValue = clsArgs)
{
    clsArgs = _parmValue;

    return clsArgs;
}

/// <summary>
///    AVA <c>parmKCS_KBVBuildingProjectTable</c> method.
/// </summary>
/// <param name="_parmValue">
///    <c>KCS_KBVBuildingProjectTable</c> as type
/// </param>
/// <returns>
///    <c>KCS_KBVBuildingProjectTable</c> as return value
/// </returns>
public KCS_KBVBuildingProjectTable parmKCS_KBVBuildingProjectTable(KCS_KBVBuildingProjectTable _parmValue = clsKCS_KBVBuildingProjectTable)
{
    clsKCS_KBVBuildingProjectTable = _parmValue;

    return clsKCS_KBVBuildingProjectTable;
}

/// <summary>
///    AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
public static void main(Args _args)
{
    AVABPMasterDataReportController controller;

    controller = AVABPMasterDataReportController::newFromArgs(_args);

    controller.parmReportName(ssrsReportStr(AVABPMasterDataReport, Report));
    controller.parmDialogCaption("@NDX:NXABPMasterDataSheet");
    controller.startOperation();
}

/// <summary>
///    AVA <c>prePromptModifyContract</c> method.
/// </summary>
protected void prePromptModifyContract()
{
    AVABPMasterDataReportContract   contract;

    clsPreviewMode = false;

    contract = this.parmReportContract().parmRdpContract();
    contract.parmBuildingProjectRefRecId(clsKCS_KBVBuildingProjectTable.RecId);
    contract.parmKCS_KBVBuildingProjectID(clsKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);
    contract.parmPrintMode(SalesTableMode::Simple);
    contract.parmShowActivities(true);
    contract.parmShowQuotations(false);
    contract.parmShowRequests(true);
    contract.parmShowRelations(true);

    // Set the target print destination to Screen if we are previewing the report.
    if(this.parmArgs())
    {
        if(this.parmArgs().menuItemName()       == menuItemActionStr(AVABPMasterDataReportActionPreview))
        {
            clsPreviewMode = true;
        }
        else if(this.parmArgs().menuItemName()  == menuItemActionStr(AVABPMasterDataReportActionPreviewAll))
        {
            clsPreviewMode = true;
            contract.parmPrintMode(SalesTableMode::Advanced);
        }
        else if(this.parmArgs().menuItemName()  == menuItemActionStr(AVABPMasterDataReportAction))
        {
            clsPreviewMode = false;
        }
        else if(this.parmArgs().menuItemName()  == menuItemOutputStr(AVABPMasterDataReportOutput))
        {
            clsPreviewMode = false;
        }
    }

    if (clsPreviewMode)
    {
        this.parmReportContract().parmPrintSettings().printMediumType(SRSPrintMediumType::Screen);
    }

    // Don't show the report dialog if Preview
    // and don't save to SysLastValue either.
    this.parmShowDialog(!clsPreviewMode);
    this.parmLoadFromSysLastValue(!clsPreviewMode);
}

/// <summary>
///    AVA <c>newFromArgs</c> method.
/// </summary>
/// <param name="_args">
///    <c>Args</c> as type
/// </param>
/// <returns>
///    <c>AVABPMasterDataReportController</c> as return value
/// </returns>
public static AVABPMasterDataReportController newFromArgs(Args _args)
{
    AVABPMasterDataReportController locController;
    Common                          locCommon;
    KCS_KBVBuildingProjectTable     locKCS_KBVBuildingProjectTable;

    //controller = new AVABPMasterDataReportController();
    locController = AVABPMasterDataReportController::construct();
    locController.parmArgs(_args);
    locController.parmLoadFromSysLastValue(false);

    if(_args)
    {
        if(_args.record().RecId)
        {
            locCommon = _args.record();
            if(     locCommon.RecId
                &&  locCommon.TableId == tableNum(KCS_KBVBuildingProjectTable))
            {
                locKCS_KBVBuildingProjectTable = locCommon;
                locController.parmKCS_KBVBuildingProjectTable(locKCS_KBVBuildingProjectTable);
            }
        }
    }

    return locController;
}
